  const area = p => { const s = p.size.slice().sort((a, b) => b - a); return s[0] * s[1]; };
  const maxArea = Math.max(...parts.map(area), 1e-12);
  const score = p => 0.55 * p.vol / maxVol + 0.45 * area(p) / maxArea;
  const ok = p => !NOT_BASE.test(p.name) && p.vol >= maxVol * 0.05;
  let pool = parts.filter(p => ok(p) && BASE_T1.test(p.name));
  if (!pool.length) pool = parts.filter(p => ok(p) && BASE_T2.test(p.name) && score(p) > 0.5);
